"""Original second-cohort knowledge items; no third-party exam content.

Each row is prompt ~ correct ~ three distractors ~ rationale ~ difficulty.
Practical competence still needs separate work samples and human review.
"""


def items(text):
    result = []
    for line in text.strip().splitlines():
        prompt, answer, distractors, rationale, level = (part.strip() for part in line.split(" ~ "))
        assert len(distractors.split("|")) == 3, prompt
        result.append((prompt, answer, distractors, rationale, int(level)))
    assert len(result) == 20
    return result


